function validate([instructions, values]) {
  const n = instructions.length;
  if (n < 1 || n > 100000) return 'instructions needs 1 to 10^5 entries.';
  if (values.length !== n) return 'instructions and values must have the same length.';
  if (instructions.some(s => s !== 'add' && s !== 'jump')) return 'Each instruction is "add" or "jump".';
  if (values.some(v => v < -100000 || v > 100000)) return 'Each value is between -10^5 and 10^5.';
  return null;
}

