function calculateScore(instructions, values) {
  const n = instructions.length;
  const visited = new Set();
  let score = 0;
  let i = 0;
  while (i >= 0 && i < n && !visited.has(i)) {
    visited.add(i);
    if (instructions[i] === "add") {
      score += values[i];
      i++;
    } else {
      i += values[i];
    }
  }
  return score;
}

