function calculateScore(instructions, values) {
  // Record the executed indexes in order, stopping at the first index already on the path.
  const path = [];
  let at = 0;
  while (at >= 0 && at < instructions.length && !path.includes(at)) {
    path.push(at);
    at = instructions[at] === 'add' ? at + 1 : at + values[at];
  }
  // Then add up the values of the "add" instructions on that path.
  let total = 0;
  for (const index of path) {
    if (instructions[index] === 'add') total += values[index];
  }
  return total;
}

