function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  if (size === 'small') {
    // Random programs: jumps are short, so they land both inside and outside the array.
    const n = 1 + Math.floor(rand() * 8);
    const instructions = Array.from({ length: n }, () => (rand() < 0.5 ? 'add' : 'jump'));
    const values = Array.from({ length: n }, () => (rand() < 0.1 ? Math.floor(rand() * 200001) - 100000 : Math.floor(rand() * (2 * n + 3)) - n - 1));
    return [instructions, values];
  }
  // Large: cut the indexes into blocks, chain some of them in a shuffled order (block 0 first) with a jump at the
  // end of each, and stop the chain by leaving the array or by jumping back to an instruction that already ran.
  const n = 2000;
  const density = pick([0.002, 0.05, 0.3]);
  const starts = [0];
  for (let i = 1; i < n; i++) if (rand() < density) starts.push(i);
  const blocks = starts.map((start, b) => [start, (b + 1 < starts.length ? starts[b + 1] : n) - 1]);
  const rest = blocks.slice(1);
  for (let i = rest.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rest[i], rest[j]] = [rest[j], rest[i]];
  }
  const order = [blocks[0], ...rest];
  const used = rand() < 0.5 ? order.length : 1 + Math.floor(rand() * order.length);
  // Inside a block the run steps forward one index at a time: mostly "add"s, with a few jumps by 1.
  const instructions = Array.from({ length: n }, () => (rand() < 0.9 ? 'add' : 'jump'));
  const values = instructions.map(s => (s === 'add' ? Math.floor(rand() * 200001) - 100000 : 1));
  for (let b = 0; b < used; b++) {
    const end = order[b][1];
    instructions[end] = 'jump';
    if (b + 1 < used) values[end] = order[b + 1][0] - end;
    else values[end] = pick([n - end, -end - 1, order[Math.floor(rand() * used)][0] - end]);
  }
  return [instructions, values];
}
